package com.mendes.scheduling_platform.platform; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component;
@Component public class PlatformAdminBootstrap implements ApplicationRunner {private final PlatformAdminRepository repo;private final PasswordEncoder encoder;private final String email,password;public PlatformAdminBootstrap(PlatformAdminRepository r,PasswordEncoder e,@Value("${PLATFORM_ADMIN_EMAIL:}") String email,@Value("${PLATFORM_ADMIN_PASSWORD:}") String password){repo=r;encoder=e;this.email=email;this.password=password;}public void run(ApplicationArguments args){if(!email.isBlank()&&!password.isBlank()&&repo.findByEmailIgnoreCase(email).isEmpty()){PlatformAdmin a=new PlatformAdmin();a.setName("Platform Admin");a.setEmail(email);a.setPassword(encoder.encode(password));repo.save(a);}}}
